A Char datatype is a datatype that is used to store a single character. It is always enclosed within a single quote (' ').
            C++

    #include <iostream>
using namespace std;

int main()
{

    char c = 'g';
    cout << c;
    return 0;
}

OutputgASCII ValueASCII Value stands for American Standard Code for Information Interchange. It is used to represent the numeric value of all the characters.ASCII Range of 'a' to 'z' =  97-122ASCII Range of 'A' to 'Z' =  65-90ASCII Range of '0' to '9' = 48-57Convert Character Value to Corresponding ASCII ValueTo convert a character to ASCII value we have to typecast it using int(character) to get the corresponding numeric value.
            C++

    #include <iostream>
using namespace std;

int main()
{
    char c = 'g';
    cout << "The Corresponding ASCII value of 'g' : ";
    cout << int(c) << endl;

    c = 'A';
    cout << "The Corresponding ASCII value of 'A' : ";
    cout << int(c) << endl;
    return 0;
}

OutputThe Corresponding ASCII value of 'g' : 103
The Corresponding ASCII value of 'A' : 65Convert ASCII Value to Corresponding Character ValueTo convert an ASCII value to a corresponding Character value we have to typecast it using char(int) to get the corresponding character value.
            C++

    #include <iostream>
using namespace std;

int main()
{
    int x = 53;
    cout << "The Corresponding character value of x is : ";
    cout << char(x) << endl;

    x = 65;
    cout << "The Corresponding character value of x is : ";
    cout << char(x) << endl;

    x = 97;
    cout << "The Corresponding character value of x is : ";
    cout << char(x) << endl;
    return 0;
}

OutputThe Corresponding character value of x is : 5
The Corresponding character value of x is : A
