            C++

    #include <iostream>
using namespace std;

int main()
{
    char a = 'G';

    // horizontal tab
    char b = '\t';
    char c = 'F';
    char d = '\t';
    char e = 'G';

    // new line
    char f = '\n';
    string s = "is the best";
    cout << a << b << c << d << e << f << s;
    return 0;
}

OutputG	F	G
is the bestTo know more about it, refer to the article - C++ Escape Sequences
